import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useEmployees } from '../../context/EmployeeContext';
import './EmployeeList.scss';

const EmployeeList = () => {
    const { employees, loading, error } = useEmployees();
    const navigate = useNavigate();

    console.log('EmployeeList rendered', { employees, loading, error });

    const handleAddClick = () => {
        navigate('/employees/add');
    };

    const handleEdit = (employeeId) => {
        navigate(`/employees/edit/${employeeId}`);
    };

    const handleDelete = (employeeId) => {
        navigate(`/employees/delete/${employeeId}`);
    };

    return (
        <div className="container">
            <div className="employee-list-section mt-4">
                <div className="card shadow-sm">
                    <div className="card-body">
                        {/* Header */}
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h5 className="card-title mb-0">Danh Sách Nhân Viên</h5>
                            <button className="btn btn-primary" onClick={handleAddClick}>
                                ➕ Thêm nhân viên
                            </button>
                        </div>

                        {/* Error message */}
                        {error && (
                            <div className="alert alert-danger" role="alert">
                                {error}
                            </div>
                        )}

                        {/* Loading spinner */}
                        {loading && (
                            <div className="text-center py-4">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Đang tải...</span>
                                </div>
                            </div>
                        )}

                        {/* Employee table */}
                        {!loading && !error && (
                            <>
                                {employees && employees.length > 0 ? (
                                    <div className="table-responsive">
                                        <table className="table table-bordered table-hover">
                                            <thead className="table-dark">
                                                <tr>
                                                    <th>Mã NV</th>
                                                    <th>Họ và tên</th>
                                                    <th>Email</th>
                                                    <th>Số điện thoại</th>
                                                    <th>Hành động</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {employees.map((emp) => (
                                                    <tr key={emp.employee_id || emp.id}>
                                                        <td>{emp.employee_id || emp.id}</td>
                                                        <td>{`${emp.first_name || ''} ${emp.last_name || ''}`}</td>
                                                        <td>{emp.email || 'N/A'}</td>
                                                        <td>{emp.phone_number || 'N/A'}</td>
                                                        <td>
                                                            <button
                                                                className="btn btn-sm btn-warning me-2"
                                                                onClick={() => handleEdit(emp.employee_id || emp.id)}
                                                            >
                                                                ✏️ Sửa
                                                            </button>
                                                            <button
                                                                className="btn btn-sm btn-danger"
                                                                onClick={() => handleDelete(emp.employee_id || emp.id)}
                                                            >
                                                                🗑️ Xóa
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                ) : (
                                    <div className="text-center py-4">
                                        <p className="text-muted mb-0">Không có nhân viên nào</p>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EmployeeList;
